def brazilian_factorial(n):
    # Brazilian factorial of n is defined as the product of all integers from 1 up to n
    # that are not divisible by 2 or 5.
    result = 1
    for i in range(1, n + 1):
        if i % 2 != 0 and i % 5 != 0:
            result *= i
    return result
