    """
    Count the number of strings of length n consisting of letters 'A' and 'B'
    without containing the substring 'AAA' or 'BBB'.
    """
    from functools import lru_cache

    @lru_cache(None)
    def dp(pos: int, last_char: str, last_count: int) -> int:
        if pos == n:
            return 1
        total = 0
        for c in ['A', 'B']:
            if c == last_char:
                if last_count < 2:
                    total += dp(pos + 1, c, last_count + 1)
            else:
                total += dp(pos + 1, c, 1)
        return total

